function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 50000) return 's needs 1 to 50000 characters.';
  if (!/^[\x00-\x7f]*$/.test(s)) return 's uses ASCII characters only.';
  if (!Number.isInteger(k) || k < 0 || k > 50) return 'k is a whole number from 0 to 50.';
  return null;
}

