function lengthOfLongestSubstringKDistinct(s, k) {
  const count = new Map();
  let left = 0;
  let best = 0;
  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    count.set(ch, (count.get(ch) || 0) + 1);
    while (count.size > k) {
      const out = s[left];
      count.set(out, count.get(out) - 1);
      if (count.get(out) === 0) {
        count.delete(out);
      }
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

