function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const letters = size === 'large' ? 2 + Math.floor(rand() * 61) : 1 + Math.floor(rand() * 5);
  const length = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const maxRun = 1 + Math.floor(rand() * (size === 'large' ? 20 : 4));
  let s = '';
  while (s.length < length) {
    const ch = alphabet[Math.floor(rand() * letters)];
    s += ch.repeat(Math.min(length - s.length, 1 + Math.floor(rand() * maxRun)));
  }
  const k = rand() < 0.1 ? 0 : rand() < 0.15 ? 50 : Math.floor(rand() * (letters + 2));
  return [s, Math.min(k, 50)];
}
